#include <stdio.h>

/* 把最大那只碗的门牌号挂到外面那张牌上 */
void pick_max(int bowls[], int n, ____out) {
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (bowls[i] > bowls[best]) {
            best = i;
        }
    }
    *out = &bowls[best];
}

int main(void) {
    int bowls[5] = {4, 9, 6, 9, 2};
    int *p = &bowls[0];

    pick_max(bowls, 5, &p);
    printf("%d\n", *p);
    return 0;
}

