#include <stdio.h>

/* 顺着两层把那只碗里的数改成 amount */
void set_through(int **pp, int amount) {
    **pp = amount;
}

int main(void) {
    int fish = 5;
    int bone = 5;
    int *p = &fish;
    int **pp = &p;

    set_through(pp, 42);
    printf("%d\n", fish);
    printf("%d\n", bone);
    printf("%d\n", **pp);
    return 0;
}
